update cutaway_layouts set script = coalesce(script, '{}'::jsonb) || $j${"title":"How a landfill works","hero":"a landfill liner","sentences":[{"role":"hook","text":"If you dig a pit and throw your trash in, you have a landfill."},{"role":"problem","text":"But trash juice leaks down into the groundwater you drink."},{"role":"fix1","text":"So you lay a clay base, but it is not enough."},{"role":"fix2","text":"You add a thick plastic sheet."},{"role":"name","text":"This is a landfill liner."},{"role":"how","text":"A pipe drains the juice into a tank."},{"role":"fact","text":"Sealed this tight, buried trash barely rots."},{"role":"factProof","text":"A 1952 newspaper dug up decades later was still readable."},{"role":"problem2","text":"But trash still makes gas, so a pipe carries it out."},{"role":"myth","text":"That flame is not waste burning, it is gas making electricity."},{"role":"finish","text":"Add a grass cap, a fence, and young trees."},{"role":"congrats","text":"Congratulations, you have built a landfill."}],"cards":[{"text":"37 YEARS","sentence":7,"word":"readable"},{"text":"480 LANDFILLS","sentence":9,"word":"electricity"}],"parts":["pit","dump truck","trash bags","trash juice seeping to the groundwater","clay base","plastic liner","drain pipe","tank","soil covers","a 1952 newspaper","gas bubbles","gas pipe","flare","generator","grass cap","fence","young trees"]}$j$::jsonb where key = 'landfill' and approved and retired_at is null;
update cutaway_layouts set script = coalesce(script, '{}'::jsonb) || $j${"title":"How a French drain works","hero":"a French drain","sentences":[{"role":"hook","text":"If you dig a ditch along your house, you have a drain."},{"role":"problem","text":"But an inch of rain pours over 600 gallons off the roof by your walls."},{"role":"flood","text":"The ditch floods."},{"role":"stakes","text":"Five feet down, it pushes over 300 pounds a square foot, and the wall cracks."},{"role":"fix1","text":"So you fill it with gravel, but water still sits."},{"role":"fix2","text":"So you lay a pipe with holes under the gravel."},{"role":"name","text":"This is a French drain."},{"role":"how","text":"Water seeps in, and the sloped pipe carries it away."},{"role":"fix3","text":"Wrap the gravel in fabric to stop mud."},{"role":"myth","text":"And the French in French drain is not France."},{"role":"mythFact","text":"It is Henry French, who wrote the book on drains in 1859."},{"role":"finish","text":"Add the grass back on top."},{"role":"congrats","text":"Congratulations, you have built a French drain."}],"cards":[{"text":"600 GALLONS","sentence":1,"word":"600"},{"text":"300 LB","sentence":3,"word":"300"},{"text":"1859","sentence":10,"word":"1859"}],"parts":["trench along the house","rain","foundation wall","crack","gravel","perforated pipe","outlet pipe","soak pit","filter fabric","mud","a French flag","an 1859 book","grass cap","bushes"]}$j$::jsonb where key = 'french_drain' and approved and retired_at is null;
update cutaway_layouts set script = coalesce(script, '{}'::jsonb) || $j${"title":"How a Car Wash Works","hero":"car wash arch","sentences":[{"role":"hook","text":"If you spray a muddy car with a hose, you have a car wash."},{"role":"problem","text":"But the mud just smears on the paint."},{"role":"fix1","text":"So you build an arch with soap sprays and cloth strips."},{"role":"problem2","text":"But the soapy water runs into the creek."},{"role":"fix2","text":"So you cut a floor drain into an underground tank."},{"role":"name","text":"This is a water reclaim tank."},{"role":"how","text":"Sand sinks, oil rises, clean water goes to a pump."},{"role":"fact","text":"That pump sends up to 80 percent back to the arch."},{"role":"myth","text":"And a car wash does not waste more than a hose."},{"role":"mythFact","text":"It uses about 15 gallons of fresh water a car; a hose uses up to 140."},{"role":"finish","text":"Add a kiosk, a vacuum, and a canopy."},{"role":"congrats","text":"Congratulations, you have built a car wash."}],"cards":[{"text":"80 PERCENT","sentence":7,"word":"80"},{"text":"15 GALLONS","sentence":9,"word":"15"},{"text":"140 GALLONS","sentence":9,"word":"140"}],"parts":["muddy car","garden hose","wash arch","soap spray","cloth strips","lawn","creek","floor drain","underground tank","sand","oil","clean water","pump","pay kiosk","vacuum station","canopy"]}$j$::jsonb where key = 'car_wash' and approved and retired_at is null;
update cutaway_layouts set script = coalesce(script, '{}'::jsonb) || $j${"sentences":[{"role":"hook","text":"If you dig a hole and fill it with water, you have a pool."},{"role":"problem","text":"But the water soaks into the soil, and the hole runs dry."},{"role":"fix1","text":"So you line it with a concrete shell, and the water stays."},{"role":"problem2","text":"But still water turns green with algae in a few warm days."},{"role":"fix2","text":"So you add a pump and a sand filter to clean the water."},{"role":"name","text":"This is a pool filter: a pump and a sand tank."},{"role":"how","text":"The pump pulls water in one pipe and pushes it out clean through the other."},{"role":"fact","text":"Every pool runs its water through the filter every 6 to 8 hours."},{"role":"congrats","text":"Congratulations, you have built a swimming pool."}]}$j$::jsonb where key = 'swimming_pool' and approved and retired_at is null;
update cutaway_layouts set layout = (replace(replace(replace(replace(replace(replace(layout::text, '"w": "dumps"', '"w": "pours"'), '"w":"dumps"', '"w":"pours"'), '"w": "slopes"', '"w": "sloped"'), '"w":"slopes"', '"w":"sloped"'), '"w": "downhill"', '"w": "carries"'), '"w":"downhill"', '"w":"carries"'))::jsonb where key = 'french_drain' and approved and retired_at is null;
